(*        bb8_list/proofs/BB92.v and Individual92.v: busycoq instantiated to 9 states, 2 symbols        *)
(* ==================================================================================================== *)

(** * Instantiating busycoq to machines with 9 states and 2 symbols (bb8 project, for the BB(9) champion; mirrors BB92.v) *)

Import Coq.Lists.List. Import ListNotations.
Export BusyCoq_Flip.
Set Default Goal Selector "!".

(* The only textual change to any inlined file.  The constructor for state H is named St_H here, with the
   abbreviation H, so that `H` is not a global constant of THIS library: when Coq invents a hypothesis name
   (anonymous `pose proof`, bare `intros`) it skips the names of globals defined in the current library, and the
   original proofs, where H came from another compiled file, rely on the invented names H, H0, ... (a renamed
   constructor behind an abbreviation is not a global for that check; patterns, notations and printing are
   unaffected: `tm (H, 0)` and `{{H}}>` mean exactly what they meant). *)
Inductive state := A | B | C | D | E | F | G | St_H | I.
Notation H := St_H.
Inductive sym := S0 | S1.

Module BB92 <: Ctx.
  Definition Q := state.
  Definition Sym := sym.
  Definition q0 := A.
  Definition q1 := B.
  Definition s0 := S0.
  Definition s1 := S1.

  Lemma q0_neq_q1 : q0 <> q1.
  Proof. discriminate. Qed.

  Lemma s0_neq_s1 : s0 <> s1.
  Proof. discriminate. Qed.

  Definition eqb_q (a b : Q): {a = b} + {a <> b}.
    decide equality.
  Defined.

  Definition eqb_sym (a b : Sym): {a = b} + {a <> b}.
    decide equality.
  Defined.

  Definition all_qs := [A; B; C; D; E; F; G; H; I].

  Lemma all_qs_spec : forall a, In a all_qs.
  Proof.
    destruct a; repeat ((left; reflexivity) || right).
  Qed.

  Definition all_syms := [S0; S1].

  Lemma all_syms_spec : forall a, In a all_syms.
  Proof.
    destruct a; repeat ((left; reflexivity) || right).
  Qed.
End BB92.

Export BusyCoq_Individual.


Module Individual92 := Individual BB92.
Export Individual92.

Declare Scope sym_scope.
Bind Scope sym_scope with Sym.
Delimit Scope sym_scope with sym.
Open Scope sym.

Notation "0" := S0 : sym_scope.
Notation "1" := S1 : sym_scope.

(* Make sure that [{{D}}>] still refers to the state, even if we shadowed
   [D] itself with something else. *)
